// Original 10th-grade items for Sam. Not copied from a textbook or an exam.
(function (root, factory) {
  var api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  if (root) root.CHEM_BANK = api;
})(typeof window !== "undefined" ? window : null, function () {
  var items = [];
  var counts = {};
  function add(topic, type, stem, choices, answer, explanation, honors) {
    var n = (counts[topic] || 0) + 1;
    counts[topic] = n;
    items.push({
      id: topic + "-" + (n < 10 ? "0" : "") + n,
      topic: topic,
      type: type,
      stem: stem,
      choices: choices,
      answer: answer,
      explanation: explanation,
      honors: !!honors
    });
  }

  add("matter", "sigfig", "How many significant figures are in 0.00450?", ["2", "3", "4", "5"], 1, "Leading zeros only place the decimal. The digits 4, 5, and the final 0 count, so there are 3.");
  add("matter", "sigfig", "How many significant figures are in 3.070?", ["2", "3", "4", "5"], 2, "The zero between 3 and 7 counts, and the trailing zero counts because a decimal point is written. That is 4.");
  add("matter", "sigfig", "How many significant figures are in 100.0?", ["1", "3", "4", "5"], 2, "The decimal point makes the trailing zeros significant. All four digits count.");
  add("matter", "sigfig", "How many significant figures are in 2.40 × 10^3?", ["2", "3", "4", "5"], 1, "In scientific notation, only the digits in the coefficient count. 2.40 has 3.");
  add("matter", "sigfig", "In this course, how many significant figures are in 1500 when no decimal point is written?", ["2", "3", "4", "ambiguous, so we call it 4"], 0, "Trailing zeros in a whole number with no decimal point are not treated as significant here. 1500 has 2. Use 1.500 × 10^3 if all four were measured.");
  add("matter", "sigfig", "Round 0.03785 to 3 significant figures.", ["0.0378", "0.0379", "0.038", "0.037"], 1, "The first three significant digits are 3, 7, and 8. The next digit is 5, so 8 rounds up and the result is 0.0379.");
  add("matter", "sigfig", "How many significant figures should the product 2.5 × 4.00 have?", ["1", "2", "3", "4"], 1, "Multiplication keeps the smaller count. 2.5 has 2 significant figures and 4.00 has 3, so the product has 2.");
  add("matter", "sigfig", "Add 12.11 and 0.5. What is the correctly rounded sum?", ["12.61", "12.6", "13", "12.60"], 1, "Addition is limited by the least precise decimal place. 0.5 is known only to the tenths place, so 12.61 rounds to 12.6.");
  add("matter", "matter", "Which change is physical?", ["Iron rusting", "Ice melting", "Wood burning", "An egg cooking"], 1, "Melting changes the state, not the substance. Rusting, burning, and cooking make new substances.");
  add("matter", "matter", "Which change is chemical?", ["Water boiling", "Salt dissolving", "Iron rusting", "Sugar melting"], 2, "Rusting turns iron into a new substance, iron oxide. The other three can be undone without changing the substance.");
  add("matter", "matter", "Which sample is a heterogeneous mixture?", ["Salt water", "Air", "Sand in water", "Pure gold"], 2, "Sand stays in pieces you can see, so the mixture is not the same throughout. Salt water and air are homogeneous. Gold is an element.");
  add("matter", "matter", "Which sample is a homogeneous mixture?", ["Sand in water", "Granite", "Salt water", "A chocolate-chip cookie"], 2, "Dissolved salt is spread evenly through the water. The other samples have visible parts.");
  add("matter", "matter", "Which substance is a compound?", ["Oxygen gas, O2", "Carbon dioxide, CO2", "Helium", "A salt-water solution"], 1, "CO2 contains two elements in a fixed ratio. O2 and helium are elements. Salt water is a mixture.");
  add("matter", "units", "A sample has a mass of 24.0 g and a volume of 8.00 mL. What is its density?", ["0.333 g/mL", "3.00 g/mL", "32.0 g/mL", "192 g/mL"], 1, "Density = mass / volume = 24.0 / 8.00 = 3.00 g/mL.");
  add("matter", "units", "Which value shows 3.50 m converted to cm with the right significant figures?", ["35.0 cm", "350 cm", "3.50 × 10^2 cm", "3.50 × 10^3 cm"], 2, "1 m = 100 cm, exactly, so 3.50 × 100 = 350 cm. Three significant figures are written 3.50 × 10^2 cm. The plain form 350 cm hides that count.");
  add("matter", "units", "What is 0.250 L in milliliters?", ["0.250 mL", "2.50 mL", "25.0 mL", "250. mL"], 3, "1 L = 1000 mL, exactly. 0.250 × 1000 = 250 mL, and the three significant figures stay.");
  add("matter", "units", "Which is the SI base unit of mass used in this course’s measurements?", ["gram", "kilogram", "pound", "mole"], 1, "The SI base unit of mass is the kilogram. The gram is the everyday lab unit, and it is 0.001 kg.");
  add("matter", "units", "What is 25°C on the kelvin scale? Use K = °C + 273.", ["25 K", "248 K", "273 K", "298 K"], 3, "25 + 273 = 298. The kelvin temperature is 298 K.");
  add("matter", "matter", "A student hits the same wrong spot on a target four times. The measurements are", ["accurate and precise", "precise but not accurate", "accurate but not precise", "neither accurate nor precise"], 1, "They agree with each other, so they are precise. They miss the accepted value, so they are not accurate.");
  add("matter", "units", "The accepted density is 2.50 g/mL and a student measures 2.40 g/mL. What is the percent error?", ["2.5%", "4.0%", "10%", "40%"], 1, "Percent error = |2.40 − 2.50| / 2.50 × 100 = 0.10 / 2.50 × 100 = 4.0%.");
  add("matter", "matter", "Which tool is the best choice for the volume of a water sample near 25 mL?", ["Beaker", "Graduated cylinder", "Balance", "Ruler"], 1, "A graduated cylinder is marked for volume. A beaker is only a rough guide. A balance measures mass.");
  add("matter", "matter", "In a closed flask, 4.0 g of hydrogen react with 32.0 g of oxygen. What is the mass of water formed if nothing escapes?", ["28.0 g", "32.0 g", "36.0 g", "128 g"], 2, "Mass is conserved. 4.0 + 32.0 = 36.0 g of water.");
  add("matter", "matter", "Which state has a definite volume but not a definite shape?", ["Solid", "Liquid", "Gas", "Plasma only"], 1, "A liquid takes the shape of the container and keeps its volume. A solid keeps both. A gas keeps neither.");
  add("matter", "matter", "Which state has neither a definite shape nor a definite volume?", ["Solid", "Liquid", "Gas", "A crystal"], 2, "A gas expands to fill the container, so both shape and volume change with the container.");
  add("matter", "matter", "Which statement describes an element?", ["It can be separated by filtering.", "It contains two kinds of atoms in a fixed ratio.", "It cannot be broken into simpler substances by a chemical change.", "It is always a mixture."], 2, "An element is one kind of atom. A compound has a fixed ratio of different atoms. A mixture can be separated physically.");
  add("matter", "units", "45.0 g of a metal occupies 15.0 cm^3. What is the density?", ["0.333 g/cm^3", "3.00 g/cm^3", "30.0 g/cm^3", "675 g/cm^3"], 1, "45.0 / 15.0 = 3.00 g/cm^3. Each measurement has three significant figures, and so does the result.");

  add("atomic", "structure", "Which particle has a charge of +1?", ["Electron", "Neutron", "Proton", "Nucleus as a whole, always"], 2, "A proton is +1, an electron is −1, and a neutron is 0. A nucleus can have many protons.");
  add("atomic", "structure", "The atomic number of an atom is the number of", ["neutrons", "protons", "protons plus neutrons", "electrons only, even in an ion"], 1, "The atomic number is the proton count. That count identifies the element.");
  add("atomic", "structure", "The mass number of an atom is", ["the proton count", "the electron count", "protons plus neutrons", "the average atomic mass"], 2, "Mass number is a count of protons and neutrons in one nucleus. Average atomic mass is a weighted decimal on the table.");
  add("atomic", "particles", "Isotopes of one element have the same number of", ["neutrons", "protons", "mass numbers", "electrons in every ion"], 1, "Isotopes share the atomic number, so they share the proton count. Their neutron counts differ.");
  add("atomic", "particles", "How many neutrons are in one atom of carbon-14?", ["6", "8", "14", "20"], 1, "Carbon has 6 protons. Neutrons = 14 − 6 = 8.");
  add("atomic", "particles", "A neutral sodium atom has 11 protons. How many electrons does it have?", ["10", "11", "12", "23"], 1, "A neutral atom has equal numbers of protons and electrons. Sodium has 11 of each.");
  add("atomic", "particles", "A sodium ion, Na+, has 11 protons. How many electrons does it have?", ["10", "11", "12", "23"], 0, "The 1+ charge means one electron was lost. 11 − 1 = 10 electrons.");
  add("atomic", "structure", "Nearly all of the mass of an atom is in the", ["electron cloud", "nucleus", "empty space", "bonds"], 1, "Protons and neutrons are in the nucleus, and they carry almost all of the mass. Electrons are light.");
  add("atomic", "structure", "Rutherford’s gold-foil experiment is best known for showing that", ["electrons orbit in fixed rings", "the atom is a uniform ball of positive charge", "the positive charge and the mass are concentrated in a tiny nucleus", "neutrons have no charge"], 2, "Most alpha particles went straight through. A few bounced back, so the positive mass is packed into a small nucleus.");
  add("atomic", "config", "Which statement matches the modern idea of an orbital?", ["A fixed track the electron must follow", "A region where an electron is likely to be found", "The nucleus of the atom", "A bond between two metals"], 1, "An orbital is a probability region, not a little planet’s path.");
  add("atomic", "config", "What is the electron configuration of a neutral sodium atom?", ["1s2 2s2 2p6 3s1", "1s2 2s2 2p6 3s2", "1s2 2s2 2p5", "1s2 2s2 2p6 3p1"], 0, "Sodium has 11 electrons. The configuration ends in 3s1, which is the one valence electron.");
  add("atomic", "config", "How many valence electrons does a neutral oxygen atom have?", ["2", "4", "6", "8"], 2, "Oxygen is in group 16. Its outer level is 2s2 2p4, so it has 6 valence electrons.");
  add("atomic", "config", "Which configuration is the chloride ion, Cl−?", ["1s2 2s2 2p6 3s2 3p5", "1s2 2s2 2p6 3s2 3p6", "1s2 2s2 2p6 3s2", "1s2 2s2 2p6 3s1"], 1, "A chlorine atom is 3s2 3p5. Gaining one electron fills 3p6, the same outer shell as argon.");
  add("atomic", "config", "When a neutral atom fills its sublevels in order, which sublevel is used before 3d?", ["4s", "4p", "5s", "3p, and then 3d immediately"], 0, "After 3p comes 4s, then 3d. The 4s sublevel is lower in energy for the atoms where it first fills.");
  add("atomic", "config", "What is the most electrons a p sublevel can hold?", ["2", "6", "10", "14"], 1, "A p sublevel has three orbitals, and each orbital holds 2 electrons. 3 × 2 = 6.");
  add("atomic", "config", "What is the most electrons one orbital can hold?", ["1", "2", "6", "8"], 1, "An orbital holds at most two electrons, and they have opposite spins.");
  add("atomic", "particles", "The average atomic mass of an element is", ["the mass number of its most common isotope", "a weighted average of its naturally occurring isotopes", "always a whole number", "the number of neutrons"], 1, "The table value mixes the isotopes by how common they are. That is why it is usually not a whole number.");
  add("atomic", "structure", "The nucleus of an atom is", ["negatively charged", "positively charged", "always neutral", "made only of electrons"], 1, "Protons make the nucleus positive. Neutrons add mass and no charge.");
  add("atomic", "structure", "Why did most alpha particles pass through the gold foil?", ["Gold has no nucleus", "The atom is mostly empty space", "Electrons are heavier than alpha particles", "The foil was a single atom thick and solid throughout"], 1, "The nucleus is tiny compared with the atom, so most of the atom is empty space.");
  add("atomic", "particles", "A calcium ion, Ca2+, has 20 protons. How many electrons does it have?", ["18", "20", "22", "40"], 0, "A 2+ charge means two electrons were lost. 20 − 2 = 18.");
  add("atomic", "particles", "What is the mass number of an iron atom with 26 protons and 30 neutrons?", ["26", "30", "56", "52"], 2, "Mass number = 26 + 30 = 56. That atom is iron-56.");
  add("atomic", "particles", "Which change turns an atom into a different element?", ["Adding a neutron", "Adding an electron", "Adding a proton", "Heating the atom"], 2, "The proton count is the atomic number. Neutrons make isotopes. Electrons make ions.");
  add("atomic", "config", "An atom in an excited state has", ["a proton in a higher energy level", "an electron in a higher energy level than its ground state", "no electrons", "a larger mass number"], 1, "Excitation moves an electron up. The nucleus is unchanged, so the element is the same.");
  add("atomic", "config", "Two electrons in the same orbital must have", ["the same spin", "opposite spins", "the same charge of +1", "different energies inside that one orbital"], 1, "The Pauli idea used in this course: an orbital holds two electrons only if their spins are opposite.");
  add("atomic", "particles", "How many protons are in an atom of iron-56?", ["26", "30", "56", "82"], 0, "Iron’s atomic number is 26, so every iron atom has 26 protons. The 56 is the mass number.");
  add("atomic", "structure", "Which particle has no charge?", ["Proton", "Electron", "Neutron", "Alpha particle"], 2, "A neutron is neutral. A proton is positive, an electron is negative, and an alpha particle is a helium nucleus with charge 2+.");

  add("periodic", "groups", "A period on the periodic table is a", ["vertical column", "horizontal row", "block of metals only", "set of isotopes"], 1, "Periods are the rows. Groups are the columns.");
  add("periodic", "groups", "The alkali metals are in", ["group 1", "group 2", "group 17", "group 18"], 0, "Group 1, except hydrogen, is the alkali metals: lithium, sodium, potassium, and so on.");
  add("periodic", "groups", "The halogens are in", ["group 1", "group 2", "group 17", "group 18"], 2, "Group 17 is the halogens: fluorine, chlorine, bromine, iodine, and astatine.");
  add("periodic", "groups", "The noble gases are in", ["group 2", "group 16", "group 17", "group 18"], 3, "Group 18 is the noble gases. They have full outer shells and are mostly unreactive.");
  add("periodic", "trends", "Going down a group, atomic radius generally", ["decreases, because a shell is lost", "increases, because a shell is added", "stays exactly the same", "depends only on the color of the cell"], 1, "Each step down adds an occupied energy level, and the atom gets larger.");
  add("periodic", "trends", "Going from left to right across a period, atomic radius generally", ["increases", "decreases", "stays the same", "drops only for noble gases"], 1, "The nucleus pulls the same energy level more tightly, so the atom gets smaller.");
  add("periodic", "trends", "Going from left to right across a period, ionization energy generally", ["decreases", "increases", "falls to zero", "stays constant"], 1, "A tighter hold on the electrons means it takes more energy to remove one. Ionization energy rises across a period.");
  add("periodic", "trends", "Which element has the highest electronegativity?", ["Francium", "Oxygen", "Fluorine", "Neon"], 2, "Fluorine is the most electronegative element. Noble gases are not given ordinary electronegativity values in this course.");
  add("periodic", "groups", "Where are the metals placed on the usual table?", ["On the right of the staircase", "On the left and in the center", "Only in group 18", "Only in the halogen column"], 1, "Metals fill the left side and the transition block. Nonmetals are on the right.");
  add("periodic", "groups", "Metalloids are best described as", ["the noble gases", "elements along the staircase between metals and nonmetals", "all of group 1", "only hydrogen"], 1, "Boron, silicon, germanium, arsenic, antimony, and tellurium sit on that staircase in this course.");
  add("periodic", "groups", "Which family is the most reactive group of metals in a first course?", ["Noble gases", "Alkaline earth metals", "Alkali metals", "Halogens"], 2, "Alkali metals have one valence electron that is lost easily. They are the most reactive metals here.");
  add("periodic", "groups", "Why are the noble gases used when a reaction is not wanted?", ["They have full outer shells and rarely react", "They are the strongest acids", "They are all liquids at room temperature", "They have the largest atoms on the table"], 0, "A full outer shell is a stable arrangement, so the noble gases are mostly unreactive.");
  add("periodic", "groups", "How many valence electrons does a neutral atom in group 2 have?", ["1", "2", "8", "18"], 1, "Group 2 atoms end in s2. They have two valence electrons.");
  add("periodic", "groups", "Why do calcium and magnesium react in similar ways?", ["They are in the same period", "They are in the same group and have the same number of valence electrons", "They have the same mass number", "They are both noble gases"], 1, "Both are alkaline earth metals, group 2, with two valence electrons.");
  add("periodic", "groups", "A typical property of many transition metals is that they", ["have only one possible ion charge", "often form colored compounds and more than one ion charge", "are all gases", "have full outer shells like helium"], 1, "Iron, copper, and their neighbors often show more than one charge, and many of their compounds are colored.");
  add("periodic", "groups", "A halogen atom commonly forms an ion with a charge of", ["1+", "2+", "1−", "0, because they never react"], 2, "A halogen has 7 valence electrons and gains one, making a 1− ion.");
  add("periodic", "trends", "Compared with its neutral atom, a positive ion is", ["larger", "smaller", "the same size", "always a noble gas"], 1, "Losing electrons lets the nucleus pull the remaining electrons closer, so the cation is smaller.");
  add("periodic", "trends", "Compared with its neutral atom, a negative ion is", ["larger", "smaller", "the same size", "missing its nucleus"], 0, "Gaining electrons increases repulsion in the outer level, so the anion is larger.");
  add("periodic", "trends", "Which atom has the lower ionization energy, cesium or sodium?", ["Cesium", "Sodium", "They are equal", "Neither has an ionization energy"], 0, "Cesium is below sodium in group 1. The outer electron is farther from the nucleus and easier to remove.");
  add("periodic", "groups", "Which element is a halogen?", ["Argon", "Bromine", "Calcium", "Iron"], 1, "Bromine is in group 17. Argon is a noble gas, calcium is an alkaline earth metal, and iron is a transition metal.");
  add("periodic", "groups", "For a main-group atom, the period number tells you the", ["number of neutrons", "highest occupied energy level", "number of isotopes", "density"], 1, "Sodium is in period 3 and its valence electron is in level 3. The period number matches that outer level.");
  add("periodic", "trends", "Inner electrons reduce the pull of the nucleus on the outer electrons. That effect is called", ["shielding", "ionization", "combustion", "dilution"], 0, "Shielding helps explain why atoms get larger and lose electrons more easily down a group.");
  add("periodic", "trends", "Moving left to right across a period, the effective nuclear charge felt by the outer electrons generally", ["decreases", "increases", "drops to zero", "equals the mass number"], 1, "Protons are added while the outer level stays the same, so the outer electrons feel a stronger pull.");
  add("periodic", "groups", "The alkaline earth metals are in", ["group 1", "group 2", "group 17", "group 18"], 1, "Group 2 is beryllium, magnesium, calcium, strontium, barium, and radium.");
  add("periodic", "groups", "Which element is a noble gas?", ["Chlorine", "Argon", "Potassium", "Oxygen"], 1, "Argon is in group 18. Chlorine is a halogen, potassium is an alkali metal, and oxygen is a nonmetal in group 16.");
  add("periodic", "groups", "A compound of a metal and a nonmetal is usually", ["ionic", "a noble gas", "held by a metallic sea of electrons only", "a homogeneous mixture"], 0, "The metal loses electrons and the nonmetal gains them. The ions attract. That is an ionic compound.");

  add("bonding", "type", "An ionic bond is best described as", ["sharing electrons between two nonmetals", "a transfer of electrons and the attraction of the ions", "a sea of electrons in a metal", "a temporary dipole only"], 1, "A metal gives electrons to a nonmetal. The positive and negative ions then attract.");
  add("bonding", "type", "A covalent bond is best described as", ["electrons transferred from a metal", "electrons shared between atoms", "a sea of electrons", "ions packed in a crystal only"], 1, "Covalent bonding is sharing, usually between two nonmetals.");
  add("bonding", "type", "A metallic bond is the attraction between", ["metal cations and a shared sea of electrons", "two nonmetal nuclei only", "a proton and a neutron", "water and oil"], 0, "The valence electrons move through the metal. That sea holds the cations together and lets the metal conduct.");
  add("bonding", "type", "Which substance is ionic?", ["CO2", "NaCl", "Cl2", "H2O"], 1, "Sodium is a metal and chlorine is a nonmetal. The others are molecular.");
  add("bonding", "type", "Which substance is molecular (covalent)?", ["NaCl", "MgO", "CO2", "KBr"], 2, "Carbon and oxygen are both nonmetals, so CO2 is molecular. The others are metal-plus-nonmetal compounds.");
  add("bonding", "type", "Which compound is ionic?", ["H2O", "CH4", "MgO", "CO2"], 2, "Magnesium is a metal and oxygen is a nonmetal. The other three formulas are made of nonmetals.");
  add("bonding", "polarity", "A bond is polar covalent when the two atoms", ["are the same element", "share electrons unequally", "transfer electrons completely", "are both noble gases"], 1, "A moderate electronegativity difference pulls the shared electrons closer to one atom. The bond is polar.");
  add("bonding", "polarity", "The bond in H2 is", ["ionic", "polar covalent", "nonpolar covalent", "metallic"], 2, "The two atoms are identical, so they share the electrons equally.");
  add("bonding", "shape", "Why is a water molecule polar?", ["It is linear and the bonds cancel", "It is bent, and the O–H bonds do not cancel", "It is a metal", "It has no lone pairs"], 1, "Oxygen has two bonds and two lone pairs. The bent shape leaves a negative end near oxygen and a positive end near the hydrogens.");
  add("bonding", "shape", "Why is CO2 nonpolar even though each C=O bond is polar?", ["The molecule is linear and the bond dipoles cancel", "Carbon is a metal", "The bonds are ionic", "CO2 has lone pairs on carbon"], 0, "The two equal bond dipoles point opposite ways in a linear molecule, so they cancel.");
  add("bonding", "properties", "Ionic compounds usually", ["melt at very low temperatures and never conduct", "have high melting points and conduct when melted or dissolved", "conduct as solids the way copper does", "are always gases"], 1, "The ion attractions are strong, so melting points are high. The ions can move, and carry charge, only when the solid is melted or dissolved.");
  add("bonding", "properties", "Many small molecular substances", ["have high melting points and conduct as solids", "have relatively low melting points and do not conduct", "are held by a sea of electrons", "are always ionic"], 1, "The bonds inside the molecule can be strong, but the attractions between molecules are weaker, so many of these substances melt easily and do not conduct.");
  add("bonding", "shape", "A Lewis dot structure shows", ["only the neutrons", "the valence electrons as dots", "the mass number", "the density"], 1, "Dots stand for valence electrons, in bonds and in lone pairs.");
  add("bonding", "shape", "The octet rule says that many main-group atoms are stable with", ["2 valence electrons, including carbon", "8 valence electrons", "18 protons", "no electrons"], 1, "Eight valence electrons is the common target. Hydrogen is the exception used here: it is stable with 2.");
  add("bonding", "shape", "Hydrogen is stable in a bond when it has", ["8 electrons", "2 electrons", "0 electrons", "18 electrons"], 1, "Hydrogen’s first shell holds 2 electrons. That filled shell is its version of a complete outer level.");
  add("bonding", "shape", "A lone pair is", ["a pair of shared bonding electrons", "a pair of valence electrons not used in a bond", "two protons", "a double bond"], 1, "Lone pairs sit on one atom. They still count as electron groups when you predict the shape.");
  add("bonding", "type", "Compared with a single bond between the same two atoms, a triple bond is", ["longer and weaker", "shorter and stronger", "the same length", "always ionic"], 1, "More shared pairs pull the nuclei closer. A triple bond is shorter and harder to break than a single bond.");
  add("bonding", "type", "Inside a polyatomic ion such as sulfate, the atoms are held by", ["covalent bonds, while the whole ion has a charge", "metallic bonds only", "no bonds at all", "neutron sharing"], 0, "The atoms share electrons. The extra charge belongs to the ion as a whole.");
  add("bonding", "properties", "An alloy such as brass is best classified as", ["an ionic crystal", "a mixture of metals with metallic bonding", "a molecular gas", "a halogen"], 1, "The metal atoms share a sea of electrons. Brass is copper and zinc.");
  add("bonding", "type", "Na+ and Cl− stay together in solid salt because", ["they share one pair of electrons equally", "opposite charges attract", "both ions are neutral", "both are nonmetals"], 1, "The positive sodium ion and the negative chloride ion attract. That attraction is the ionic bond.");
  add("bonding", "polarity", "In this course, sodium and chlorine are treated as ionic because", ["they are the same element", "the electronegativity difference is large", "both are nonmetals", "sodium is a noble gas"], 1, "A large difference means the electrons are transferred, not shared. Sodium and chlorine are the classroom example.");
  add("bonding", "shape", "Water is bent rather than linear because", ["oxygen has lone pairs that push the bonds", "hydrogen is a metal", "the molecule has no electrons", "carbon is the central atom"], 0, "Two lone pairs on oxygen repel the two bonding pairs. The bonds are pushed into a bent shape.");
  add("bonding", "shape", "What is the shape of methane, CH4?", ["Bent", "Linear", "Tetrahedral", "A flat square"], 2, "Carbon has four bonding pairs and no lone pairs. The four bonds point to the corners of a tetrahedron.");
  add("bonding", "properties", "Which solid conducts electricity without being melted?", ["Table salt", "Sugar", "Copper metal", "Dry ice"], 2, "Copper’s electron sea can move. Solid salt’s ions are locked in place. Sugar and dry ice are molecular.");
  add("bonding", "properties", "Diamond has a very high melting point because", ["it is a small molecule with weak attractions between molecules", "every carbon atom is locked in a network of covalent bonds", "it is an ionic salt", "it is a noble gas"], 1, "Breaking diamond means breaking covalent bonds throughout the solid, not just pulling molecules apart.");
  add("bonding", "polarity", "Which bond is polar covalent?", ["H–H", "Cl–Cl", "H–Cl", "Na–Cl, treated as ionic here"], 2, "Hydrogen and chlorine share electrons, but chlorine pulls harder, so H–Cl is polar covalent. H–H and Cl–Cl are nonpolar. Na–Cl is ionic in this course.");

  add("nomenclature", "ionic", "What is the name of NaCl?", ["sodium chlorate", "sodium chloride", "nitrogen chloride", "chlorine sodide"], 1, "The metal keeps its name. The nonmetal ending changes to -ide. NaCl is sodium chloride.");
  add("nomenclature", "ionic", "What is the name of CaCl2?", ["calcium chloride", "calcium(II) chloride", "carbon chloride", "chlorine calcide"], 0, "Calcium is in group 2 and always forms 2+ in this course, so no Roman numeral is used. Two chlorides balance it. The name is calcium chloride.");
  add("nomenclature", "ionic", "What is the name of Fe2O3?", ["iron oxide", "iron(II) oxide", "iron(III) oxide", "iron(VI) oxide"], 2, "Three oxide ions are 6− altogether. Two iron ions must be 3+ each. The name is iron(III) oxide.");
  add("nomenclature", "ionic", "What is the name of CuO?", ["copper oxide", "copper(I) oxide", "copper(II) oxide", "copper(IV) oxide"], 2, "Oxide is 2−, so the copper ion is 2+. The Stock name is copper(II) oxide.");
  add("nomenclature", "molecular", "What is the name of N2O4?", ["nitrogen oxide", "dinitrogen tetroxide", "nitrogen tetraoxide", "dinitrogen dioxide"], 1, "Two nitrogen atoms and four oxygen atoms use the prefixes di- and tetra-. The second element ends in -ide.");
  add("nomenclature", "molecular", "What is the name of CO?", ["carbon monoxide", "monocarbon monoxide", "carbon dioxide", "cobalt"], 0, "One oxygen is signaled with mono- on the second element. The first element does not get a mono- prefix. CO is carbon monoxide.");
  add("nomenclature", "molecular", "What is the name of CO2?", ["carbon monoxide", "carbon dioxide", "dicarbon oxide", "cobalt dioxide"], 1, "One carbon is unnamed as a prefix, and two oxygens make dioxide. CO2 is carbon dioxide.");
  add("nomenclature", "molecular", "What is the name of SF6?", ["sulfur fluoride", "monosulfur hexafluoride", "sulfur hexafluoride", "hexasulfur fluoride"], 2, "Six fluorine atoms use hexa-. The name is sulfur hexafluoride.");
  add("nomenclature", "acid", "What is the name of HCl(aq)?", ["chloric acid", "hydrochloric acid", "hydrogen chlorite", "chlorous acid"], 1, "A binary acid uses hydro- and -ic. HCl in water is hydrochloric acid.");
  add("nomenclature", "acid", "What is the name of H2SO4?", ["sulfurous acid", "sulfuric acid", "hydrosulfuric acid", "hydrogen sulfate gas"], 1, "The sulfate ion’s acid is sulfuric acid. One fewer oxygen, sulfite, would be sulfurous acid.");
  add("nomenclature", "acid", "What is the name of H2SO3?", ["sulfuric acid", "sulfurous acid", "hydrosulfuric acid", "sulfur dioxide"], 1, "Sulfite has one fewer oxygen than sulfate, so the acid ending is -ous. H2SO3 is sulfurous acid.");
  add("nomenclature", "acid", "What is the name of HNO3?", ["nitrous acid", "nitric acid", "hydronitric acid", "nitrogen trioxide"], 1, "Nitrate’s acid is nitric acid. Nitrous acid is HNO2.");
  add("nomenclature", "ionic", "What is the name of Na2SO4?", ["sodium sulfide", "sodium sulfite", "sodium sulfate", "sodium sulfate dioxide"], 2, "SO4 2− is sulfate. Two sodium ions balance the 2− charge. The name is sodium sulfate.");
  add("nomenclature", "ionic", "What is the name of KNO2?", ["potassium nitrate", "potassium nitrite", "potassium nitride", "potassium nitrogen oxide"], 1, "NO2 − is nitrite. NO3 − would be nitrate. The name is potassium nitrite.");
  add("nomenclature", "ionic", "What is the name of NH4Cl?", ["nitrogen chloride", "ammonia chloride", "ammonium chloride", "ammonium chlorate"], 2, "NH4 + is ammonium and Cl− is chloride. The name is ammonium chloride.");
  add("nomenclature", "ionic", "What is the name of Ca(OH)2?", ["calcium oxide", "calcium hydroxide", "calcium(II) hydrate", "carbon hydroxide"], 1, "OH− is hydroxide. Two of them balance Ca2+. The name is calcium hydroxide.");
  add("nomenclature", "ionic", "What is the formula of aluminum oxide?", ["AlO", "Al2O3", "Al3O2", "AlO2"], 1, "Aluminum is 3+ and oxide is 2−. The criss-cross gives Al2O3.");
  add("nomenclature", "ionic", "What is the name of PbO2?", ["lead oxide", "lead(II) oxide", "lead(IV) oxide", "lead dioxide, with no charge named"], 2, "Two oxides are 4− altogether, so lead is 4+. The Stock name is lead(IV) oxide.");
  add("nomenclature", "ionic", "What is the name of ZnCl2?", ["zinc(II) chloride", "zinc chloride", "zinc dichloride", "zinc chlorate"], 1, "Zinc has a fixed 2+ charge in this course, so no Roman numeral is written. The name is zinc chloride.");
  add("nomenclature", "ionic", "What is the name of AgNO3?", ["silver(I) nitrate", "silver nitrate", "silver nitrite", "argon nitrate"], 1, "Silver’s charge is fixed, so no numeral is used. NO3 − is nitrate. The name is silver nitrate.");
  add("nomenclature", "molecular", "What is the name of P2O5?", ["phosphorus oxide", "diphosphorus pentoxide", "phosphorus pentoxide, with no prefix on phosphorus", "pentaphosphorus dioxide"], 1, "Two phosphorus atoms and five oxygen atoms: diphosphorus pentoxide.");
  add("nomenclature", "acid", "What is the name of HBr(aq)?", ["hydrobromic acid", "bromic acid", "bromous acid", "hydrogen bromide oxide"], 0, "HBr is a binary acid: hydro- plus the root plus -ic. The name is hydrobromic acid.");
  add("nomenclature", "ionic", "What is the name of Na2CO3?", ["sodium carbonide", "sodium carbonate", "sodium carbonite", "disodium carbon monoxide"], 1, "CO3 2− is carbonate. The name is sodium carbonate.");
  add("nomenclature", "ionic", "What is the name of FeCl2?", ["iron chloride", "iron(II) chloride", "iron(III) chloride", "chlorine ferride"], 1, "Two chloride ions are 2− altogether, so iron is 2+. The name is iron(II) chloride.");
  add("nomenclature", "molecular", "What is the name of SO3?", ["sulfur monoxide", "sulfur trioxide", "trisulfur oxide", "sulfite"], 1, "One sulfur and three oxygens: sulfur trioxide. Sulfite is the ion SO3 2−, not this molecule.");
  add("nomenclature", "acid", "What is the name of H3PO4?", ["phosphorous acid", "phosphoric acid", "hydrophosphoric acid", "phosphorus tetraoxide"], 1, "The phosphate ion’s acid is phosphoric acid. Phosphorous acid has one fewer oxygen.");

  add("mole", "moles", "A mole of any substance contains", ["6.022 × 10^23 particles", "22.4 particles", "1 particle", "100 particles"], 0, "Avogadro’s number, 6.022 × 10^23, is the count in one mole.");
  add("mole", "molar-mass", "Using H = 1.01 and O = 16.00, what is the molar mass of water?", ["17.01 g/mol", "18.02 g/mol", "16.00 g/mol", "34.02 g/mol"], 1, "2(1.01) + 16.00 = 18.02 g/mol.");
  add("mole", "moles", "Using C = 12.01 and O = 16.00, what is the mass of 2.00 mol of CO2?", ["44.01 g", "88.02 g", "22.01 g", "48.00 g"], 1, "CO2 is 12.01 + 32.00 = 44.01 g/mol. 2.00 × 44.01 = 88.02 g.");
  add("mole", "moles", "Using H = 1.01 and O = 16.00, how many moles are in 36.04 g of water?", ["1.00 mol", "2.00 mol", "18.02 mol", "0.500 mol"], 1, "Water is 18.02 g/mol. 36.04 / 18.02 = 2.00 mol.");
  add("mole", "moles", "Using Na = 22.99 and Cl = 35.45, what is the mass of 0.500 mol of NaCl?", ["29.22 g", "58.44 g", "116.88 g", "0.500 g"], 0, "NaCl is 58.44 g/mol. Half a mole is 29.22 g.");
  add("mole", "moles", "What percent of the mass of water is hydrogen? Use H2O = 18.02 g/mol and the two hydrogens = 2.02 g.", ["2.02%", "11.2%", "18.0%", "88.8%"], 1, "2.02 / 18.02 × 100 = 11.2%. The rest is oxygen.");
  add("mole", "stoich", "An empirical formula shows", ["the actual count of atoms in a molecule", "the simplest whole-number ratio", "only the metal", "the percent yield"], 1, "The empirical formula is the smallest ratio. The molecular formula may be a multiple of it.");
  add("mole", "stoich", "The molecular formula of glucose is C6H12O6. What is the empirical formula?", ["C6H12O6", "CH2O", "C2H4O2", "CHO"], 1, "Divide every subscript by 6. The simplest ratio is CH2O.");
  add("mole", "stoich", "In 2 H2 + O2 → 2 H2O, how many moles of O2 react with 4.0 mol of H2?", ["1.0 mol", "2.0 mol", "4.0 mol", "8.0 mol"], 1, "The ratio of O2 to H2 is 1:2. 4.0 × 1/2 = 2.0 mol O2.");
  add("mole", "stoich", "In N2 + 3 H2 → 2 NH3, how many moles of NH3 form from 2.0 mol of N2 if hydrogen is plentiful?", ["1.0 mol", "2.0 mol", "3.0 mol", "4.0 mol"], 3, "The ratio of NH3 to N2 is 2:1. 2.0 × 2 = 4.0 mol NH3.");
  add("mole", "stoich", "The limiting reactant is the reactant that", ["has the larger mass", "runs out first and sets the amount of product", "is written first in the equation", "is always water"], 1, "The limiting reactant is used up. The product amount is calculated from it, not from the leftover reactant.");
  add("mole", "stoich", "The excess reactant is", ["the one that runs out", "the one left over after the limiting reactant is gone", "the catalyst", "the product"], 1, "Some of the excess reactant is still there when the reaction stops.");
  add("mole", "stoich", "Theoretical yield is", ["the measured mass from the lab", "the calculated maximum mass of product", "always larger than 100%", "the mass of the limiting reactant only"], 1, "The theoretical yield comes from the balanced equation and the limiting reactant. The lab amount is the actual yield.");
  add("mole", "stoich", "A reaction’s theoretical yield is 8.0 g and the actual yield is 6.0 g. What is the percent yield?", ["48%", "75%", "133%", "14%"], 1, "Percent yield = 6.0 / 8.0 × 100 = 75%.");
  add("mole", "moles", "At STP in this course, one mole of an ideal gas occupies", ["1.00 L", "22.4 L", "100 L", "6.022 L"], 1, "STP here is 0°C and 1 atm. The molar volume used is 22.4 L.");
  add("mole", "moles", "How many particles are in 2.00 mol? Use 6.022 × 10^23 per mole and four significant figures.", ["3.011 × 10^23", "6.022 × 10^23", "1.204 × 10^24", "1.204 × 10^23"], 2, "2.00 × 6.022 × 10^23 = 1.204 × 10^24. The mole count is exact in this problem, and 6.022 has four significant figures.");
  add("mole", "molar-mass", "Molar mass is expressed in", ["g", "mol", "g/mol", "L/mol only"], 2, "Molar mass is the mass of one mole, so the unit is grams per mole.");
  add("mole", "moles", "The particles counted in one mole of NaCl are called", ["molecules", "formula units", "neutrons", "liters"], 1, "Ionic compounds are not molecules. One mole of NaCl is 6.022 × 10^23 formula units.");
  add("mole", "moles", "Using O = 16.00, what is the mass of 3.00 mol of O2?", ["16.00 g", "32.00 g", "48.00 g", "96.00 g"], 3, "O2 is 32.00 g/mol. 3.00 × 32.00 = 96.00 g.");
  add("mole", "moles", "Using H = 1.01, how many moles are in 10.0 g of H2?", ["2.02 mol", "4.95 mol", "10.0 mol", "20.2 mol"], 1, "H2 is 2.02 g/mol. 10.0 / 2.02 = 4.95 mol.");
  add("mole", "stoich", "In a balanced equation, the coefficients give", ["the gram ratio only", "the mole ratio", "the neutron ratio", "the density"], 1, "A coefficient counts moles (or molecules). Convert to grams only after you use that ratio.");
  add("mole", "stoich", "The first step in a mass-to-mass problem is usually to", ["multiply the two masses", "convert the given mass to moles", "change a subscript", "divide by 22.4 even when the substance is a solid"], 1, "The mole ratio only works in moles. Start by dividing the given mass by its molar mass.");
  add("mole", "moles", "Avogadro’s number counts", ["only atoms of elements, never ions", "atoms, molecules, or formula units, depending on the substance", "only gases", "grams"], 1, "A mole is a count. What is being counted depends on the formula: atoms, molecules, or formula units.");
  add("mole", "moles", "Which sample contains more moles: 18.02 g of water or 44.01 g of CO2? Use those numbers as the molar masses.", ["Water", "CO2", "They are equal", "It cannot be decided"], 2, "18.02 g of water is 1 mol, and 44.01 g of CO2 is 1 mol. The mole counts are equal.");
  add("mole", "stoich", "A compound’s empirical formula is CH2 and its molar mass is about 28 g/mol. What is the molecular formula? The empirical mass is about 14 g/mol.", ["CH2", "C2H4", "C3H6", "CH4"], 1, "28 / 14 = 2, so the molecular formula is twice the empirical formula: C2H4.");
  add("mole", "molar-mass", "Using Ca = 40.08, C = 12.01, and O = 16.00, what is the molar mass of CaCO3?", ["68.08 g/mol", "84.08 g/mol", "100.09 g/mol", "116.09 g/mol"], 2, "40.08 + 12.01 + 3(16.00) = 40.08 + 12.01 + 48.00 = 100.09 g/mol.");

  add("reactions", "balance", "Which set of coefficients balances H2 + O2 → H2O?", ["1, 1, 1", "2, 1, 2", "2, 2, 2", "1, 2, 1"], 1, "Two H2 give four H atoms, and two water molecules also have four H atoms. One O2 supplies the two O atoms. The set is 2, 1, 2.");
  add("reactions", "balance", "Which set of coefficients balances Fe + O2 → Fe2O3?", ["2, 3, 1", "4, 3, 2", "1, 1, 1", "3, 2, 1"], 1, "Four Fe on the left match two Fe2O3. Three O2 give six O atoms, and two Fe2O3 also have six. The set is 4, 3, 2.");
  add("reactions", "balance", "Which set of coefficients balances KClO3 → KCl + O2?", ["1, 1, 1", "2, 2, 3", "2, 1, 3", "3, 2, 2"], 1, "Two KClO3 give six O atoms, which is three O2. Potassium and chlorine then match as 2 and 2. The set is 2, 2, 3.");
  add("reactions", "type", "Two reactants joining to make one product is a", ["synthesis", "decomposition", "single replacement", "combustion only"], 0, "Synthesis builds one product from simpler reactants. A + B → AB is the pattern.");
  add("reactions", "type", "One reactant breaking into simpler products is a", ["synthesis", "decomposition", "double replacement", "neutralization"], 1, "Decomposition is AB → A + B. One substance comes apart.");
  add("reactions", "type", "Zn + CuSO4 → ZnSO4 + Cu is a", ["synthesis", "single replacement", "double replacement", "combustion"], 1, "Zinc takes the place of copper. One element replaces another in a compound.");
  add("reactions", "type", "AgNO3 + NaCl → AgCl + NaNO3 is a", ["single replacement", "double replacement", "decomposition", "combustion"], 1, "The positive ions trade partners. That is double replacement.");
  add("reactions", "type", "Complete combustion of a hydrocarbon in oxygen produces", ["CO and H2 only", "CO2 and H2O", "C and H2", "a metal oxide"], 1, "Enough oxygen turns the carbon into CO2 and the hydrogen into H2O.");
  add("reactions", "predict", "Using the course activity list, what happens when zinc metal is placed in CuSO4 solution?", ["No reaction", "ZnSO4 and copper metal form", "CuSO4 stays and zinc ion is unchanged", "Water is the only product"], 1, "Zinc is above copper on the list, so zinc replaces Cu2+. The products are ZnSO4 and Cu.");
  add("reactions", "predict", "Using the course activity list, what happens when copper metal is placed in ZnSO4 solution?", ["Copper replaces zinc", "No reaction", "Zn metal and CuSO4 form", "The solution becomes a noble gas"], 1, "Copper is below zinc, so copper cannot replace Zn2+. There is no reaction.");
  add("reactions", "predict", "What product forms from the synthesis 2 Na + Cl2 → ?", ["NaCl2", "NaCl", "Na2Cl", "Cl only"], 1, "Sodium is 1+ and chloride is 1−, so the compound is NaCl. The balanced equation is 2 Na + Cl2 → 2 NaCl.");
  add("reactions", "predict", "The precipitate in AgNO3(aq) + NaCl(aq) → is", ["NaNO3", "AgCl", "AgNO3", "water"], 1, "Silver chloride is the insoluble solid in this pair. Sodium nitrate stays dissolved.");
  add("reactions", "predict", "Which statement matches the short solubility guide?", ["All nitrates are insoluble", "Nitrate salts dissolve", "All chlorides are insoluble", "Alkali-metal salts are insoluble"], 1, "Nitrates dissolve. Alkali-metal salts and ammonium salts also dissolve in this guide.");
  add("reactions", "predict", "AgCl is classified in this course as", ["soluble", "insoluble", "a gas", "an acid"], 1, "The short guide treats silver chloride as an exception that does not dissolve.");
  add("reactions", "balance", "Why must a chemical equation be balanced?", ["So the ink looks even", "Atoms are not created or destroyed", "So every coefficient is 1", "To change the products"], 1, "A reaction rearranges atoms. The count of each kind of atom has to match on both sides.");
  add("reactions", "balance", "When you balance an equation you may change", ["subscripts", "coefficients", "the element symbols", "the charges of the nuclei"], 1, "A coefficient changes the number of formula units. A subscript would change the substance.");
  add("reactions", "type", "The symbol (aq) means the substance is", ["a solid crystal", "dissolved in water", "a gas", "insoluble"], 1, "Aqueous means dissolved in water. (s), (l), and (g) are solid, liquid, and gas.");
  add("reactions", "type", "A catalyst written above the arrow is", ["a product", "used up as a reactant", "not consumed; it speeds the reaction", "the precipitate"], 2, "The catalyst is there at the end as well as the start. It is not a product in the equation.");
  add("reactions", "balance", "Which equation is balanced?", ["H2 + O2 → H2O", "2 H2 + O2 → 2 H2O", "CH4 + O2 → CO2 + H2O", "Fe + O2 → Fe2O3"], 1, "2 H2 + O2 → 2 H2O has 4 H and 2 O on each side. The others do not.");
  add("reactions", "balance", "Which set balances CH4 + O2 → CO2 + H2O?", ["1, 1, 1, 1", "1, 2, 1, 2", "2, 1, 1, 2", "1, 2, 2, 1"], 1, "One CH4 needs two O2 to make one CO2 and two H2O. Carbon, hydrogen, and oxygen then match.");
  add("reactions", "type", "HCl + NaOH → NaCl + H2O is a", ["combustion", "neutralization", "single replacement", "decomposition"], 1, "An acid and a hydroxide base make a salt and water. That reaction is neutralization.");
  add("reactions", "type", "Which list is the diatomic elements used in this course?", ["He, Ne, Ar", "H2, N2, O2, F2, Cl2, Br2, I2", "Na, K, Fe", "C, S, P only"], 1, "Those seven elements are written as pairs when they are pure elements in an equation.");
  add("reactions", "type", "The symbol (g) means", ["dissolved", "solid", "gas", "glass"], 2, "(g) is gas. (s) is solid, (l) is liquid, and (aq) is aqueous.");
  add("reactions", "balance", "An equation with coefficients 2, 4, 2 should usually be simplified to", ["2, 4, 2", "1, 2, 1", "4, 8, 4", "0, 0, 0"], 1, "Every coefficient is divisible by 2. The simplest whole-number set is 1, 2, 1.");
  add("reactions", "predict", "A halogen higher on the activity idea can replace", ["a halogen ion below it", "any metal", "a noble gas", "a proton in the nucleus"], 0, "Chlorine can replace bromide, for example, because chlorine is more reactive. The pattern matches single replacement.");
  add("reactions", "balance", "Which set of coefficients balances Al + O2 → Al2O3?", ["1, 1, 1", "2, 3, 1", "4, 3, 2", "2, 1, 2"], 2, "Four aluminum atoms and six oxygen atoms on each side: 4 Al + 3 O2 → 2 Al2O3.");

  add("gases", "theory", "In the kinetic-molecular model, gas particles are", ["packed in a rigid lattice", "far apart and moving randomly", "not moving", "always liquid"], 1, "The model treats gas particles as far apart, in constant random motion.");
  add("gases", "theory", "Gas pressure on a container comes from", ["particles colliding with the walls", "the color of the gas", "neutrons in the nucleus", "the balance"], 0, "Each collision with the wall pushes on it. Many collisions make the pressure.");
  add("gases", "law", "Gas-law calculations in this course use temperature in", ["Celsius only", "kelvin", "Fahrenheit", "any scale, with no conversion"], 1, "Charles’s law and the ideal gas law need an absolute scale. Convert Celsius by adding 273.");
  add("gases", "law", "Boyle’s law says that at constant temperature", ["pressure and volume move in opposite directions", "pressure and volume both double together", "volume depends only on the gas name", "temperature must change"], 0, "P1 V1 = P2 V2. If pressure goes up and temperature stays put, volume goes down.");
  add("gases", "law", "Charles’s law says that at constant pressure", ["volume and kelvin temperature move together", "volume falls as kelvin temperature rises", "pressure must change", "moles must change"], 0, "V1 / T1 = V2 / T2. A higher kelvin temperature means a larger volume when pressure is constant.");
  add("gases", "law", "The combined gas law relates", ["only mass and volume", "pressure, volume, and temperature", "only moles and mass", "density and color"], 1, "P1 V1 / T1 = P2 V2 / T2. Use it when pressure and temperature both change.");
  add("gases", "law", "The ideal gas law is", ["PV = nRT", "P/V = nRT", "V = m/d only", "q = mcΔT"], 0, "PV = nRT connects pressure, volume, moles, and kelvin temperature.");
  add("gases", "law", "STP in this course means", ["25°C and 1 atm", "0°C and 1 atm", "100°C and 1 atm", "0 K and 1 atm"], 1, "Standard temperature here is 0°C, which is 273 K, and standard pressure is 1 atm.");
  add("gases", "law", "0°C is equal to", ["0 K", "100 K", "273 K", "373 K"], 2, "Add 273. The freezing point of water is 273 K on the scale used here.");
  add("gases", "law", "A gas is at constant temperature and the pressure doubles. The volume", ["doubles", "is cut in half", "stays the same", "becomes zero"], 1, "Boyle’s law: pressure and volume are inversely related. Twice the pressure means half the volume.");
  add("gases", "law", "A gas is at constant pressure and the kelvin temperature doubles. The volume", ["is cut in half", "doubles", "stays the same", "drops by 273 L"], 1, "Charles’s law: volume is proportional to kelvin temperature. Double T means double V.");
  add("gases", "law", "Volume is measured at two temperatures while pressure stays constant. Which law is that?", ["Boyle", "Charles", "Dilution", "Boyle and a changing pressure"], 1, "Volume and temperature, with pressure held still, is Charles’s law.");
  add("gases", "theory", "A real gas behaves least like an ideal gas when", ["pressure is low and temperature is high", "pressure is very high and temperature is very low", "it is helium at room conditions", "the container is large"], 1, "Particles take up space and attract each other when they are crowded and slow. Those are the conditions that break the ideal picture.");
  add("gases", "law", "Avogadro’s hypothesis, as used here, says that equal volumes of gases at the same temperature and pressure have equal", ["masses", "numbers of moles", "densities, always", "colors"], 1, "The volume depends on the number of particles, not on the identity of the gas, under the same T and P.");
  add("gases", "law", "When P is in atm and V is in L, the R used in this course is", ["0.0821 L·atm/(mol·K)", "8.314 L·atm/(mol·K)", "22.4 L·atm/(mol·K)", "1.00 L·atm/(mol·K)"], 0, "0.0821 matches atmospheres and liters. 8.314 is the joule version and is not the one for these PV = nRT problems.");
  add("gases", "law", "A gas has P1 = 2.0 atm and V1 = 6.0 L. The temperature stays the same and the pressure becomes 3.0 atm. What is V2?", ["1.0 L", "4.0 L", "9.0 L", "12 L"], 1, "V2 = P1 V1 / P2 = (2.0 × 6.0) / 3.0 = 4.0 L.");
  add("gases", "law", "A gas has a volume of 2.00 L at 300 K. The pressure stays the same and the temperature becomes 450 K. What is the new volume?", ["1.33 L", "2.00 L", "3.00 L", "4.50 L"], 2, "V2 = 2.00 × (450 / 300) = 3.00 L. The temperatures are already in kelvin.");
  add("gases", "law", "If the volume and the temperature of a gas stay the same and more moles are added, the pressure", ["falls", "rises", "stays the same", "becomes the volume"], 1, "PV = nRT. A larger n, with V and T fixed, means a larger P.");
  add("gases", "theory", "A barometer measures", ["the mass of a gas sample", "atmospheric pressure", "the molar mass", "temperature only"], 1, "A barometer is a pressure instrument for the air. The common comparison used here is 1 atm = 760 mmHg.");
  add("gases", "law", "In this course, 1 atm is equal to", ["100 mmHg", "273 mmHg", "760 mmHg", "22.4 mmHg"], 2, "The conversion used here is 1 atm = 760 mmHg, and it is treated as exact.");
  add("gases", "theory", "The ideal-gas model treats the volume of the particles themselves as", ["most of the container", "negligible", "equal to 22.4 L each", "the cause of pressure"], 1, "The model says the particles are points compared with the space between them. That fails when the gas is highly compressed.");
  add("gases", "theory", "In the ideal model, collisions of gas particles are", ["sticky, so energy is lost", "elastic, so kinetic energy is not lost", "impossible", "only with the walls, never with each other"], 1, "Elastic collisions keep the total kinetic energy. The particles do collide with each other and with the walls.");
  add("gases", "theory", "Temperature, in the kinetic model, measures", ["the number of moles", "the average kinetic energy of the particles", "the color", "the molar mass"], 1, "A higher temperature means a higher average kinetic energy. It is not the same thing as the total heat in the sample.");
  add("gases", "theory", "At the same temperature, lighter gas particles", ["move more slowly on average", "move faster on average", "stop", "have a higher molar mass"], 1, "The same average kinetic energy and a smaller mass means a higher average speed.");
  add("gases", "law", "Absolute zero on the scale used here is", ["0°C", "−273°C", "273°C", "100 K"], 1, "0 K is −273°C in this course. It is the bottom of the kelvin scale, not a lab temperature you reach.");
  add("gases", "law", "A sealed balloon is left in a hot car and the pressure inside stays about the same. What happens to the volume?", ["It decreases, by Boyle’s law", "It increases, by Charles’s law", "It becomes zero", "It becomes the molar mass"], 1, "The kelvin temperature rises and the pressure does not, so the volume rises. That is Charles’s law.");

  add("solutions", "solubility", "In a solution, the solute is", ["the substance that dissolves", "always water", "the container", "the precipitate"], 0, "The solute is the substance that gets dissolved. The solvent does the dissolving.");
  add("solutions", "molarity", "Molarity is", ["moles of solute per liter of solution", "grams per milliliter of solvent only", "moles per kilogram, always", "liters per mole"], 0, "M = moles of solute / liters of solution. The volume is the finished solution, not the solvent alone.");
  add("solutions", "molarity", "What is the molarity of a solution with 0.50 mol of solute in 2.0 L of solution?", ["0.25 M", "1.0 M", "2.5 M", "4.0 M"], 0, "0.50 / 2.0 = 0.25 M.");
  add("solutions", "dilution", "The dilution relationship used here is", ["M1 / V1 = M2 / V2", "M1 V1 = M2 V2", "M1 + V1 = M2 + V2", "M1 = M2 always"], 1, "Moles of solute stay the same, so the product of molarity and volume stays the same.");
  add("solutions", "dilution", "What volume of 2.0 M stock is needed to prepare 100 mL of 0.50 M solution?", ["10 mL", "25 mL", "50 mL", "200 mL"], 1, "V1 = (0.50 × 100) / 2.0 = 25 mL.");
  add("solutions", "solubility", "“Like dissolves like” means", ["every solid dissolves in every liquid", "polar solvents dissolve many polar and ionic solutes", "oil is the best solvent for salt", "water dissolves only gases"], 1, "A polar solvent such as water dissolves many ionic compounds and polar molecules. Nonpolar solvents dissolve nonpolar substances.");
  add("solutions", "solubility", "A saturated solution", ["can dissolve more solute at that temperature", "holds as much solute as it can at that temperature", "has no solute", "is always supersaturated"], 1, "Saturated means the dissolved amount is at the limit for that temperature. Undissolved solid can sit next to it.");
  add("solutions", "solubility", "An unsaturated solution", ["can dissolve more solute", "has solid that will not dissolve", "is past the solubility limit", "has no solvent"], 0, "The concentration is below the solubility. More solute can still dissolve.");
  add("solutions", "solubility", "A supersaturated solution", ["is below the solubility limit", "holds more dissolved solute than the usual limit and is unstable", "contains no solute", "is a pure solid"], 1, "It is past the normal maximum. A disturbance can make the extra solute come out of solution.");
  add("solutions", "solubility", "For most solids in water, solubility", ["falls as the water gets hotter", "rises as the water gets hotter", "does not depend on temperature", "is zero above 0°C"], 1, "A warmer solvent usually lets more of a solid dissolve. Gases are the opposite.");
  add("solutions", "solubility", "A gas dissolved in water usually becomes", ["more soluble as the water is heated", "less soluble as the water is heated", "a solid", "independent of temperature"], 1, "Heating gives the gas particles energy to leave the solution, so solubility falls.");
  add("solutions", "solubility", "An electrolyte", ["does not dissolve", "produces ions and the solution conducts", "is always sugar", "is always a gas"], 1, "Ions carry the current. NaCl is an electrolyte. Sugar is not.");
  add("solutions", "solubility", "Sugar dissolved in water is", ["a strong electrolyte", "a nonelectrolyte", "always a precipitate", "a halogen"], 1, "Sugar molecules stay molecules. The solution does not conduct the way a salt solution does.");
  add("solutions", "solubility", "NaCl in water is", ["a nonelectrolyte", "a strong electrolyte", "insoluble", "a network solid"], 1, "It separates into Na+ and Cl−, and the solution conducts.");
  add("solutions", "molarity", "“Concentrated” means", ["the solute is a strong acid", "there is a relatively large amount of solute in the solution", "the solution is saturated with a gas", "the solvent is not water"], 1, "Concentration is about how much solute is present. Strength is about whether an acid or base ionizes completely.");
  add("solutions", "solubility", "Mass percent of a solution is", ["mass of solute / mass of solution × 100", "moles / liters", "volume of solute only", "always the molarity"], 0, "Mass percent uses masses. Molarity uses moles and liters. They are different measures.");
  add("solutions", "molarity", "The right way to prepare a solution of a set molarity is to", ["fill the flask with solvent, then add the solute on top", "dissolve the solute and then add solvent until the solution reaches the mark", "boil the solvent away", "add the solute with no solvent"], 1, "The volume in the molarity is the volume of the finished solution. Fill to the mark after the solute is in.");
  add("solutions", "molarity", "A problem gives 250 mL and asks for molarity. Before you divide, convert that volume to", ["0.250 L", "2.50 L", "250 L", "25.0 L"], 0, "Molarity uses liters. 250 mL = 0.250 L.");
  add("solutions", "molarity", "What is the molarity of 0.10 mol of solute in 250 mL of solution?", ["0.040 M", "0.25 M", "0.40 M", "2.5 M"], 2, "250 mL = 0.250 L. 0.10 / 0.250 = 0.40 M.");
  add("solutions", "dilution", "Adding water to a solution", ["increases the moles of solute", "does not change the moles of solute", "changes the solute into the solvent", "raises the molarity"], 1, "The same amount of solute is now in a larger volume, so the molarity falls and the moles stay the same.");
  add("solutions", "solubility", "In an aqueous solution the solvent is", ["oil", "water", "the solute", "air"], 1, "Aqueous means water is the solvent.");
  add("solutions", "solubility", "A precipitate is", ["a dissolved gas", "an insoluble solid that forms from solution", "the solvent", "a catalyst"], 1, "The solid falls out because it does not stay dissolved. AgCl is the usual example.");
  add("solutions", "solubility", "On a solubility curve, a point above the curve for a solid usually means the solution is", ["unsaturated", "supersaturated, or holding undissolved solid", "pure solvent", "a gas"], 1, "The curve is the saturated amount. Above it, the system is past that amount.");
  add("solutions", "solubility", "Adding a solute to water can raise the boiling point of the water. This idea is", ["a change in the solvent’s properties caused by the dissolved particles", "a change in the chemical formula of water", "Boyle’s law", "a nuclear change"], 0, "The dissolved particles affect how the solvent boils. The water molecules are still H2O. This is an honors-side idea in this course.", true);
  add("solutions", "molarity", "Which solution is the most concentrated?", ["0.10 M", "0.25 M", "0.80 M", "0.05 M"], 2, "0.80 mol per liter is the largest molarity in the list.");
  add("solutions", "dilution", "You have 50.0 mL of 1.20 M NaCl and you dilute it to 200.0 mL. What is the new molarity?", ["0.300 M", "0.600 M", "1.20 M", "4.80 M"], 0, "M2 = (1.20 × 50.0) / 200.0 = 60 / 200 = 0.300 M. The moles did not change.");

  add("acids", "properties", "An Arrhenius acid", ["produces OH− in water", "produces H+ in water", "is always insoluble", "is a noble gas"], 1, "Arrhenius acids release H+ in water. Arrhenius bases release OH−.");
  add("acids", "properties", "An Arrhenius base", ["produces H+ in water", "produces OH− in water", "donates neutrons", "is always a gas"], 1, "The Arrhenius base used in this course makes hydroxide ions in water. NaOH is the example.");
  add("acids", "ph", "A solution with pH 3.0 is", ["acidic", "neutral", "basic", "a solid element"], 0, "pH below 7 is acidic. 7 is neutral. Above 7 is basic.");
  add("acids", "ph", "A solution with pH 10.0 is", ["acidic", "neutral", "basic", "a strong acid"], 2, "10 is above 7, so the solution is basic.");
  add("acids", "ph", "At 25°C in this course, a neutral solution has pH", ["0", "1", "7", "14"], 2, "Neutral means [H+] = [OH−], and that pH is 7 on the scale used here.");
  add("acids", "ph", "The relationship used here is", ["pH × pOH = 14", "pH + pOH = 14.00", "pH = pOH always", "pH − pOH = 1"], 1, "pH and pOH add to 14.00 at the temperature used in these problems.");
  add("acids", "ph", "What is the pH when [H+] = 1.0 × 10^−3 M?", ["3.00", "11.00", "1.00", "0.001"], 0, "pH = −log(1.0 × 10^−3) = 3.00. 11.00 would be the pOH.");
  add("acids", "ph", "A solution has pH 2.00. What is [H+]?", ["1.0 × 10^−2 M", "1.0 × 10^−12 M", "2.0 M", "1.0 × 10^−7 M"], 0, "[H+] = 10^(−pH) = 1.0 × 10^−2 M.");
  add("acids", "ph", "What is the pH when the pOH is 3.00?", ["3.00", "11.00", "7.00", "17.00"], 1, "pH = 14.00 − 3.00 = 11.00.");
  add("acids", "strength", "A strong acid", ["ionizes only a little", "ionizes completely in water", "is always concentrated", "does not contain hydrogen"], 1, "Strong means complete ionization. Concentrated means there is a lot of it. Those are different words.");
  add("acids", "strength", "Which acid is weak?", ["HCl", "HNO3", "Acetic acid", "H2SO4"], 2, "Acetic acid ionizes only partly. HCl, HNO3, and H2SO4 are on the strong-acid list used here.");
  add("acids", "strength", "Which compound is a strong base in this course?", ["NH3", "Acetic acid", "NaOH", "H2O"], 2, "NaOH ionizes completely to Na+ and OH−. Ammonia is a weak base here.");
  add("acids", "properties", "Neutralization of a strong acid with a hydroxide base produces", ["only a gas", "a salt and water", "two acids", "a metal and oxygen"], 1, "H+ and OH− make water, and the remaining ions make the salt.");
  add("acids", "properties", "The products of HCl + NaOH are", ["NaCl and H2O", "NaH and ClOH", "H2 and NaClO", "Na and Cl2"], 0, "The salt is NaCl and the other product is water.");
  add("acids", "properties", "An indicator is used to", ["taste the acid", "show a color change that signals the pH region", "measure mass", "balance an equation"], 1, "The color is a signal. You do not taste lab acids or bases.");
  add("acids", "ph", "In an acidic solution", ["[H+] is greater than [OH−]", "[OH−] is greater than [H+]", "both are zero", "pH is 14"], 0, "Extra H+ is what makes the solution acidic. The pH is then below 7.");
  add("acids", "ph", "If [H+] becomes 10 times larger, the pH", ["rises by 1", "falls by 1", "stays the same", "becomes 14"], 1, "The pH is a negative log. A factor of 10 in [H+] changes the pH by 1, downward when [H+] rises.");
  add("acids", "properties", "A description of acids as sour is", ["a reason to taste the lab chemical", "background only; lab chemicals are not tasted", "true of every base", "a test you should do"], 1, "The old description is not a lab test. Do not taste unknowns.");
  add("acids", "properties", "Bases are sometimes described as bitter or slippery. In lab you should", ["rub every base between your fingers", "not touch or taste them; the description is not a test", "taste a drop to classify them", "heat them in an open beaker to decide"], 1, "Those descriptions are background. Bases can burn skin. Use indicators or pH, not your hands or your mouth.");
  add("acids", "ph", "What is the pH of 1.0 × 10^−5 M HCl? Treat it as a strong acid and ignore water’s own ions.", ["5.00", "9.00", "1.00", "7.00"], 0, "[H+] = 1.0 × 10^−5 M, so the pH is 5.00.");
  add("acids", "ph", "What is the pH of 1.0 × 10^−2 M NaOH? Treat it as a strong base.", ["2.00", "12.00", "7.00", "1.00"], 1, "[OH−] = 1.0 × 10^−2, so pOH = 2.00 and pH = 12.00.");
  add("acids", "ph", "The water constant used here is", ["[H+][OH−] = 1.0 × 10^−14", "[H+] + [OH−] = 1", "[H+] = 14", "pH = 0 always"], 0, "That product is 1.0 × 10^−14. It is why pH and pOH add to 14.");
  add("acids", "strength", "A 0.001 M HCl solution is", ["weak and concentrated", "strong and dilute", "weak and dilute", "not an acid"], 1, "HCl ionizes completely, so it is strong. 0.001 M is a small concentration, so it is dilute.");
  add("acids", "properties", "What is the formula of sulfuric acid?", ["H2SO3", "H2SO4", "HCl", "HNO3"], 1, "Sulfuric acid is H2SO4. H2SO3 is sulfurous acid.");
  add("acids", "properties", "A Brønsted–Lowry acid is a", ["proton donor", "proton acceptor", "electron sea", "neutron donor"], 0, "The acid gives away H+. The base accepts it. NaOH is still a base because OH− can take the proton.");
  add("acids", "ph", "Which solution has the higher [H+], pH 2.00 or pH 5.00?", ["pH 2.00", "pH 5.00", "They are equal", "pH 5.00, because 5 is larger"], 0, "A lower pH means a larger [H+]. pH 2 is 1.0 × 10^−2 M, and pH 5 is 1.0 × 10^−5 M.");

  add("thermo", "energy", "An exothermic process", ["absorbs heat and has a positive ΔH", "releases heat and has a negative ΔH", "has no energy change", "always cools the surroundings"], 1, "Heat leaves the system. ΔH is negative, and the surroundings get warmer.");
  add("thermo", "energy", "An endothermic process", ["releases heat", "absorbs heat and has a positive ΔH", "has ΔH = 0 always", "freezes the surroundings"], 1, "Heat enters the system. ΔH is positive, and the surroundings can feel cooler.");
  add("thermo", "energy", "The system is", ["everything outside the experiment", "the part you are watching", "only the thermometer", "the room air, always"], 1, "You choose the system. The surroundings are everything else.");
  add("thermo", "calorimetry", "The heat equation for a temperature change is", ["q = mcΔT", "PV = nRT", "M1 V1 = M2 V2", "pH = −log[H+]"], 0, "q is heat, m is mass, c is specific heat, and ΔT is the temperature change.");
  add("thermo", "calorimetry", "When a problem does not give another value, the specific heat of liquid water used here is", ["1.00 J/g°C", "4.18 J/g°C", "100 J/g°C", "0.0821 J/g°C"], 1, "4.18 J/g°C is the value for liquid water in this course.");
  add("thermo", "calorimetry", "How much heat raises 10.0 g of water by 5.00°C? Use c = 4.18 J/g°C.", ["20.9 J", "41.8 J", "209 J", "418 J"], 2, "q = 10.0 × 4.18 × 5.00 = 209 J.");
  add("thermo", "energy", "On a heating curve, a flat segment means", ["the thermometer is broken", "a phase change is happening", "the substance is cooling", "the mass is zero"], 1, "The heat goes into changing the state. The temperature stays constant until that change is finished.");
  add("thermo", "energy", "Melting is", ["endothermic", "exothermic", "a nuclear change", "a change with ΔH = 0"], 0, "The solid takes in heat to become liquid. ΔH for melting is positive.");
  add("thermo", "energy", "Freezing is", ["endothermic", "exothermic", "impossible for water", "a rise in temperature"], 1, "The liquid releases heat as it becomes solid. The surroundings can warm.");
  add("thermo", "energy", "Activation energy is", ["the heat released by the reaction", "the minimum energy needed for a successful collision", "the molar mass", "q = mcΔT"], 1, "Particles must meet with at least this energy. A catalyst lowers it. The idea is shared with the kinetics lesson.");
  add("thermo", "energy", "Enthalpy, H, is the", ["heat content used to track ΔH", "speed of the reaction", "pH", "volume of a gas"], 0, "ΔH is the enthalpy change. Negative means exothermic in this course.");
  add("thermo", "energy", "The law of conservation of energy says", ["energy can vanish", "energy lost by one part is gained by another, aside from work you are told to ignore", "heat and temperature are the same", "mass always becomes energy in lab reactions"], 1, "Track the system and the surroundings. What one loses, the other gains, in the problems used here.");
  add("thermo", "calorimetry", "Calorimetry is a way to", ["measure a heat transfer from a temperature change", "count protons", "balance an equation", "find the pH directly"], 0, "You measure mass and ΔT, then use q = mcΔT.");
  add("thermo", "energy", "Temperature and heat are", ["the same quantity", "different: temperature is the reading, heat is energy transferred", "both measured in grams", "both equal to ΔH"], 1, "A spark and a bathtub can have the same high temperature and very different amounts of heat.");
  add("thermo", "energy", "The joule is a unit of", ["energy", "mass", "volume", "amount of substance"], 0, "Heat is calculated in joules in these problems. Mass is in grams and amount is in moles.");
  add("thermo", "energy", "When water freezes, the surroundings", ["gain heat", "lose heat", "change element", "stay at absolute zero"], 0, "Freezing is exothermic for the water. The heat released warms the surroundings.");
  add("thermo", "calorimetry", "ΔT in q = mcΔT is", ["the initial temperature only", "final temperature minus initial temperature", "always 100", "the specific heat"], 1, "A rise is positive. A drop is negative, which means the system lost heat.");
  add("thermo", "calorimetry", "A substance with a high specific heat", ["changes temperature easily", "needs more energy for the same temperature change", "cannot be heated", "has no mass"], 1, "Water’s high specific heat is why 4.18 J raises only one gram by one degree.");
  add("thermo", "energy", "Combustion of a fuel is", ["endothermic", "exothermic", "a phase change only", "a gas law"], 1, "Burning releases heat. ΔH is negative.");
  add("thermo", "energy", "Photosynthesis stores energy in glucose. For the plant system it is treated as", ["exothermic", "endothermic", "a freezing process", "a neutralization"], 1, "The plant takes in energy. The surroundings, in the form of light, supply it. ΔH for that direction is positive.");
  add("thermo", "energy", "When the system loses heat, q for the system is", ["positive", "negative", "zero", "equal to the mass"], 1, "Heat leaving the system is a negative q. The surroundings then have a positive q of the same size.");
  add("thermo", "energy", "Hess’s law says the total enthalpy change", ["depends on the path you imagine", "depends only on the start and the end", "is always zero", "equals the activation energy"], 1, "You can add steps. The overall ΔH is the same as the direct path. This is an honors tool here.", true);
  add("thermo", "energy", "Breaking a bond", ["releases energy", "requires energy", "has no energy change", "is always exothermic for the pair of atoms"], 1, "Pulling bonded atoms apart takes energy. Forming a bond releases energy. This comparison is an honors idea here.", true);
  add("thermo", "calorimetry", "The same amount of heat is added to 20 g of water and 20 g of a metal with a lower specific heat. The metal’s temperature", ["rises more", "rises less", "falls", "cannot change"], 0, "A lower specific heat means less energy is needed for each degree, so ΔT is larger.");
  add("thermo", "calorimetry", "In q = mcΔT, the units work out to energy when", ["c is in J/g°C, m is in g, and ΔT is in °C", "c is in grams", "ΔT is in moles", "m is in joules"], 0, "g cancels, and °C cancels, leaving joules.");
  add("thermo", "energy", "While ice at 0°C melts, the temperature of the ice-water mix", ["rises steadily", "stays at 0°C until the ice is gone", "falls to −10°C", "jumps to 100°C"], 1, "The heat is used for the phase change. The temperature stays on the plateau.");

  add("kinetics", "rate", "The rate of a reaction describes", ["how fast reactants become products", "only the final amount", "the molar mass", "the pH"], 0, "Rate is about time. Yield is about how much you get. They are different questions.");
  add("kinetics", "rate", "Raising the temperature usually", ["slows every reaction", "speeds the reaction", "stops equilibrium", "changes the element"], 1, "More collisions have enough energy when the particles are moving faster.");
  add("kinetics", "rate", "Raising the concentration of a reactant in solution usually", ["lowers the collision rate", "raises the collision rate and often the reaction rate", "has no effect", "removes the catalyst"], 1, "More particles in the same volume means more collisions.");
  add("kinetics", "rate", "A catalyst", ["is used up as a product", "speeds the reaction and is not consumed", "raises the activation energy", "shifts equilibrium toward products"], 1, "The catalyst is there at the end. It gives a path with a lower activation energy.");
  add("kinetics", "rate", "A catalyst changes the rate by", ["lowering the activation energy", "raising the temperature of the room", "changing ΔH to zero", "removing a product"], 0, "The hill the particles must climb is lower. Both directions are helped, so equilibrium amounts stay put.");
  add("kinetics", "rate", "A powdered solid reacts faster than a chunk of the same mass because", ["the powder has more surface", "the powder has a lower temperature", "the chunk has more collisions", "mass is not conserved"], 0, "More surface means more places for collisions with the other reactant.");
  add("kinetics", "rate", "Collision theory says a reaction needs collisions that have", ["enough energy and a useful orientation", "any energy, if the particles touch", "no orientation requirement", "a catalyst in every case"], 0, "A gentle collision, or one at the wrong angle, does not make products.");
  add("kinetics", "rate", "Activation energy is", ["the energy of the products", "the minimum energy for a successful collision", "the heat of the room", "ΔH"], 1, "It is the hill on the energy diagram, from the reactants up to the transition state.");
  add("kinetics", "equilibrium", "At equilibrium", ["the forward and reverse rates are equal", "the reactions have stopped", "the amounts must be equal", "only the forward reaction happens"], 0, "Both directions keep going. Their rates match, so the amounts stay constant.");
  add("kinetics", "equilibrium", "At equilibrium the amounts of reactants and products", ["are constant, but not necessarily equal", "are always equal", "are always zero", "keep rising"], 0, "Constant does not mean equal. One side can be much larger and still be steady.");
  add("kinetics", "equilibrium", "Adding more of a reactant to a system at equilibrium shifts the reaction", ["toward the products", "toward the reactants", "not at all", "only if a catalyst is present"], 0, "Le Chatelier: the system uses up some of what you added. More product forms.", true);
  add("kinetics", "equilibrium", "For an exothermic reaction, heating the system shifts it", ["toward the products", "toward the reactants", "not at all", "toward a higher ΔH of zero only"], 1, "Heat is treated as a product of an exothermic reaction. Adding heat pushes the reaction back toward the reactants.", true);
  add("kinetics", "equilibrium", "Raising the pressure on a gas equilibrium shifts the reaction toward", ["the side with more moles of gas", "the side with fewer moles of gas", "the side with more solids", "neither side, ever"], 1, "The smaller number of gas particles takes up less space. Higher pressure favors that side.", true);
  add("kinetics", "equilibrium", "A large equilibrium constant, K much greater than 1, means", ["reactants are favored", "products are favored", "the reaction is fast", "the reaction has stopped"], 1, "K compares products to reactants at equilibrium. A large K means a lot of product. It does not tell you the rate.", true);
  add("kinetics", "equilibrium", "Adding a catalyst to a system at equilibrium", ["shifts it toward products", "shifts it toward reactants", "does not shift it; equilibrium is reached sooner", "changes K"], 2, "Both directions speed up by the same idea. The amounts at equilibrium stay the same.");
  add("kinetics", "equilibrium", "A reversible reaction is drawn with", ["a single arrow", "a double arrow", "no arrow", "an equals sign only"], 1, "The double arrow means the reverse reaction happens too.");
  add("kinetics", "equilibrium", "Equilibrium amounts stay steady only when the system is", ["open, so gas can leave", "closed, so nothing is added or removed", "at absolute zero", "a mixture of two solids with no contact"], 1, "If a gas escapes, the amounts change and the system is not at equilibrium.");
  add("kinetics", "rate", "Which change increases the rate of the reaction of hydrochloric acid with marble chips?", ["Using larger chips", "Cooling the acid", "Using the acid more concentrated, or crushing the chips", "Removing the acid"], 2, "A higher concentration and more surface both increase useful collisions.");
  add("kinetics", "rate", "The peak of an energy diagram is the", ["product energy", "transition state", "catalyst", "enthalpy of the reactants only"], 1, "The transition state is the high-energy arrangement the particles pass through.");
  add("kinetics", "equilibrium", "On an energy diagram, if the products are lower than the reactants, the forward reaction is", ["endothermic", "exothermic", "at equilibrium with K = 1 always", "impossible"], 1, "The system loses enthalpy. ΔH is negative, which is exothermic.");
  add("kinetics", "rate", "A fast reaction", ["must go to completion", "can still stop with mostly reactants if equilibrium favors them", "has no activation energy", "has K = 0"], 1, "Rate says how quickly you get to equilibrium. It does not say which side is favored.");
  add("kinetics", "equilibrium", "If the reaction quotient Q is smaller than K, the reaction", ["goes forward toward products", "goes backward toward reactants", "has stopped", "needs a new element"], 0, "Q below K means there is not yet enough product. The forward direction runs until Q equals K.", true);
  add("kinetics", "rate", "Stirring helps a reaction between a solid and a solution because", ["fresh solution reaches the solid surface", "it lowers the temperature to 0°C", "it changes the balanced equation", "it removes the activation energy entirely"], 0, "Stirring replaces the used-up solution at the surface, so collisions continue.");
  add("kinetics", "equilibrium", "Equilibrium is dynamic, which means", ["both directions continue", "every particle has stopped", "only the forward reaction remains", "the temperature is absolute zero"], 0, "The amounts look still because the two rates match, not because the chemistry has frozen.");
  add("kinetics", "equilibrium", "Removing a product from an equilibrium shifts the reaction", ["toward the products", "toward the reactants", "not at all", "only if the reaction is a nuclear change"], 0, "The system replaces what you removed. More reactant is turned into product.", true);
  add("kinetics", "rate", "Which statement about a catalyst is true?", ["It is consumed and becomes a product", "It lowers the activation energy and is still there at the end", "It changes the balanced equation", "It makes an endothermic reaction exothermic"], 1, "The path changes. The start, the end, and ΔH do not.");

  return items;
});
